import os
import sys
import json
from .backup_utils import backup_existing_file


AHCLAUDE_DIR = os.path.expanduser("~/.ahdev")
SETTINGS_FILE = os.path.expanduser("~/.claude/settings.json")


def log_error(msg: str):
    print(f"\n\033[31m[错误] {msg}\033[0m", file=sys.stderr)


def log_warning(msg: str):
    print(f"\n\033[33m[警告] {msg}\033[0m")


def log_success(msg: str):
    print(f"\033[32m{msg}\033[0m")


def get_ahclaude_cmd():
    import shutil
    import sys

    def to_bash_path(path: str) -> str:
        normalized = path.replace("\\", "/")
        if len(normalized) >= 2 and normalized[1] == ":":
            drive = normalized[0].lower()
            rest = normalized[2:]
            if rest.startswith("/"):
                return f"/{drive}{rest}"
            return f"/{drive}/{rest}"
        return normalized

    cmd = shutil.which("auto++")
    if cmd:
        if sys.platform == "win32":
            return f'"{to_bash_path(cmd)}"'
        return cmd

    python_exec = sys.executable
    if sys.platform == "win32":
        return f'"{to_bash_path(python_exec)}" -m ahclaude_plugin'
    return f'"{python_exec}" -m ahclaude_plugin'

def load_settings():
    if os.path.exists(SETTINGS_FILE):
        try:
            with open(SETTINGS_FILE, 'r', encoding='utf-8') as f:
                return json.load(f)
        except json.JSONDecodeError as e:
            log_warning(f"settings.json 格式错误: {e}")
            return {}
        except IOError as e:
            log_warning(f"读取 settings.json 失败: {e}")
            return {}
    return {}


def save_settings(settings):
    try:
        content = json.dumps(settings, ensure_ascii=False, indent=2)
        backup_existing_file(SETTINGS_FILE, "Claude Code settings.json", content)
        with open(SETTINGS_FILE, 'w', encoding='utf-8') as f:
            f.write(content)
    except IOError as e:
        log_error(f"保存 settings.json 失败: {e}")
        raise


def remove_ahclaude_env(settings: dict) -> bool:
    """移除 ahclaude 添加的 env 配置"""
    if "env" not in settings:
        return False

    ahclaude_env_keys = [
        "ANTHROPIC_BASE_URL",
        "CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC",
        "ANTHROPIC_AUTH_TOKEN",
        "ANTHROPIC_MODEL",
        "ANTHROPIC_DEFAULT_HAIKU_MODEL",
        "ANTHROPIC_DEFAULT_SONNET_MODEL",
        "ANTHROPIC_DEFAULT_OPUS_MODEL",
    ]

    removed = False
    for key in ahclaude_env_keys:
        if key in settings["env"]:
            del settings["env"][key]
            removed = True
            print(f"已移除环境变量: {key}")

    if not settings["env"]:
        del settings["env"]

    return removed


def remove_hooks():
    settings = load_settings()

    env_removed = remove_ahclaude_env(settings)

    if env_removed:
        save_settings(settings)
        print(f"已清理 auto++ 配置")
        return True

    print("未找到 auto++ 配置")
    return False


def uninstall():
    print("=" * 50)
    print("auto++ 卸载向导")
    print("=" * 50)
    print()

    try:
        print("[步骤 1] 移除环境变量...")
        remove_hooks()

        print()
        print("=" * 50)
        log_success("移除配置完成!")
        print("=" * 50)
        print()
        print("请重启 Claude Code 以使更改生效")

    except KeyboardInterrupt:
        log_warning("\n移除配置已取消")
        sys.exit(1)
    except Exception as e:
        log_error(f"移除配置失败: {e}")
        sys.exit(1)


if __name__ == "__main__":
    uninstall()
